/* CSS PART 1 OF 2 */

:root {
  --ink: #202b32;
  --ink-soft: #53616a;
  --navy: #182d3a;
  --navy-deep: #10232e;
  --accent: #c87942;
  --accent-dark: #a85d30;
  --paper: #f7f6f2;
  --white: #ffffff;
  --line: #e2e2dc;
  --container: 1180px;
  --gutter: clamp(22px, 5vw, 76px);
  --radius: 5px;
  --shadow: 0 18px 55px rgba(16, 35, 46, .13);
  --font-body: "Inter", "Helvetica Neue", Arial, sans-serif;
  --font-heading: "Georgia", "Times New Roman", serif;
}

*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
}

body {
  margin: 0;
  color: var(--ink);
  background: var(--paper);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, textarea, select {
  font: inherit;
}

button, a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

h1, h2, h3, p {
  margin-top: 0;
}

h1, h2, h3 {
  font-family: var(--font-heading);
  font-weight: 500;
  line-height: 1.12;
  letter-spacing: -.035em;
}

h1 {
  font-size: clamp(3rem, 7.5vw, 6.4rem);
}

h2 {
  font-size: clamp(2.3rem, 4.6vw, 4rem);
}

h3 {
  font-size: clamp(1.45rem, 2vw, 1.9rem);
}

p {
  color: var(--ink-soft);
}

.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: clamp(76px, 10vw, 132px);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--accent-dark);
  font-size: .73rem;
  font-weight: 800;
  letter-spacing: .17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 2px;
  background: var(--accent);
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: 48px;
}

.section-heading h2 {
  margin-bottom: 20px;
}

.section-heading p {
  max-width: 610px;
  font-size: 1.05rem;
}

.site-header {
  position: relative;
  z-index: 10;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 43, 50, .08);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  color: var(--navy);
}

.brand-mark {
  display: grid;
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  place-items: center;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--paper);
}

.brand-mark img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.brand-name {
  font-family: var(--font-heading);
  font-size: 1.12rem;
  font-weight: 700;
}

.brand-description {
  margin-top: 5px;
  color: var(--ink-soft);
  font-size: .63rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(18px, 3vw, 38px);
}

.primary-nav a:not(.button) {
  color: var(--ink);
  font-size: .86rem;
  font-weight: 650;
  transition: color .2s ease;
}

.primary-nav a:not(.button):hover {
  color: var(--accent-dark);
}

.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  padding: 14px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--accent);
  color: var(--white);
  font-size: .83rem;
  font-weight: 800;
  letter-spacing: .035em;
  text-align: center;
  transition: background .2s ease, transform .2s ease;
}

.button:hover {
  transform: translateY(-2px);
  background: var(--accent-dark);
}

.button-dark {
  background: var(--navy);
}

.button-dark:hover {
  background: var(--navy-deep);
}

.button-outline {
  border-color: rgba(255, 255, 255, .65);
  background: transparent;
  color: var(--white);
}

.button-outline:hover {
  background: var(--white);
  color: var(--navy);
}

.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - 88px));
  align-items: center;
  overflow: hidden;
  background: var(--navy-deep);
  color: var(--white);
}

.hero-media {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 45%;
}

.hero::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(12, 29, 39, .91) 0%,
    rgba(12, 29, 39, .76) 43%,
    rgba(12, 29, 39, .25) 100%
  );
  content: "";
}

.hero-content {
  position: relative;
  z-index: 1;
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
  padding-block: 100px;
}

.hero .eyebrow {
  color: #f0b486;
}

.hero h1 {
  max-width: 790px;
  margin-bottom: 25px;
  color: var(--white);
}

.hero h1 em {
  color: #efb486;
  font-weight: 400;
}

.hero-description {
  max-width: 570px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, .86);
  font-size: clamp(1rem, 1.6vw, 1.17rem);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 13px;
}

.hero-proof {
  display: flex;
  flex-wrap: wrap;
  gap: 26px;
  margin-top: 55px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, .3);
}

.hero-proof-item {
  color: rgba(255, 255, 255, .88);
  font-size: .78rem;
  font-weight: 650;
  letter-spacing: .04em;
}

.hero-proof-item strong {
  display: block;
  margin-bottom: 4px;
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.65rem;
  font-weight: 500;
}

.intro-section {
  background: var(--paper);
}

.intro-layout {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  align-items: center;
  gap: clamp(45px, 8vw, 110px);
}

.intro-copy h2 {
  max-width: 610px;
}

.intro-copy p {
  max-width: 570px;
}

.intro-image-wrap {
  position: relative;
  min-height: 460px;
}

.intro-image {
  width: 100%;
  height: 460px;
  object-fit: cover;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.intro-caption {
  position: absolute;
  right: -20px;
  bottom: 24px;
  max-width: 235px;
  padding: 20px 24px;
  background: var(--navy);
  color: var(--white);
  box-shadow: var(--shadow);
}

.intro-caption strong {
  display: block;
  font-family: var(--font-heading);
  font-size: 1.7rem;
  font-weight: 500;
}

.intro-caption span {
  color: rgba(255, 255, 255, .75);
  font-size: .77rem;
}

.services-section {
  background: var(--navy);
  color: var(--white);
}

.services-section .section-heading h2 {
  color: var(--white);
}

.services-section .section-heading p {
  color: rgba(255, 255, 255, .72);
}

.services-layout {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: rgba(255, 255, 255, .18);
  border: 1px solid rgba(255, 255, 255, .18);
}

.service-item {
  min-height: 225px;
  padding: 35px 30px;
  background: var(--navy);
}

.service-number {
  display: block;
  margin-bottom: 28px;
  color: #efb486;
  font-family: var(--font-heading);
  font-size: 1.2rem;
}

.service-item h3 {
  margin-bottom: 13px;
  color: var(--white);
}

.service-item p {
  margin-bottom: 0;
  color: rgba(255, 255, 255, .7);
  font-size: .91rem;
}

.projects-section {
  background: var(--white);
}

.projects-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}

.project-feature {
  position: relative;
  min-height: 490px;
  overflow: hidden;
  background: var(--navy);
}

.project-feature img {
  width: 100%;
  height: 100%;
  min-height: 490px;
  object-fit: cover;
  transition: transform .5s ease;
}

.project-feature:hover img {
  transform: scale(1.035);
}

.project-secondary {
  display: grid;
  grid-template-rows: 1fr 1fr;
  gap: 28px;
}

.project-secondary-item {
  position: relative;
  min-height: 230px;
  overflow: hidden;
  background: var(--navy);
}

.project-secondary-item img {
  width: 100%;
  height: 100%;
  min-height: 230px;
  object-fit: cover;
  transition: transform .5s ease;
}

.project-secondary-item:hover img {
  transform: scale(1.035);
}

.project-overlay {
  position: absolute;
  inset: auto 0 0;
  padding: 60px 28px 24px;
  background: linear-gradient(transparent, rgba(12, 29, 39, .88));
  color: var(--white);
}

.project-overlay span {
  display: block;
  margin-bottom: 7px;
  color: #f0b486;
  font-size: .7rem;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.project-overlay h3 {
  margin: 0;
  color: var(--white);
  font-size: 1.55rem;
}

.process-section {
  background: #eeede7;
}

.process-layout {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  gap: clamp(45px, 8vw, 100px);
}

.process-intro {
  max-width: 460px;
}

.process-list {
  border-top: 1px solid #d2d1c9;
}

.process-step {
  display: grid;
  grid-template-columns: 65px 1fr;
  gap: 20px;
  padding: 27px 0;
  border-bottom: 1px solid #d2d1c9;
}

.process-step-number {
  color: var(--accent-dark);
  font-family: var(--font-heading);
  font-size: 1.8rem;
}

.process-step h3 {
  margin-bottom: 8px;
  font-size: 1.45rem;
}

.process-step p {
  margin-bottom: 0;
}
```

