/* CSS PART 2 OF 2 */

.contact-section {
  position: relative;
  overflow: hidden;
  background: var(--navy-deep);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 110px);
}

.contact-copy h2 {
  color: var(--white);
}

.contact-copy > p {
  max-width: 450px;
  color: rgba(255, 255, 255, .72);
}

.contact-details {
  display: grid;
  gap: 18px;
  margin-top: 35px;
}

.contact-detail {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.contact-detail-label {
  color: #efb486;
  font-size: .7rem;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.contact-detail a {
  width: fit-content;
  color: var(--white);
  font-size: 1.12rem;
  font-weight: 650;
}

.contact-detail a:hover {
  color: #efb486;
}

.contact-form {
  display: grid;
  gap: 19px;
  padding: clamp(25px, 4vw, 45px);
  border-radius: var(--radius);
  background: var(--white);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.form-heading h3 {
  margin-bottom: 8px;
  color: var(--navy);
}

.form-heading p {
  margin-bottom: 8px;
  font-size: .9rem;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.form-field {
  display: grid;
  gap: 7px;
}

.form-field label {
  color: var(--ink);
  font-size: .8rem;
  font-weight: 750;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid #d6d9d8;
  border-radius: 3px;
  background: #fbfbf9;
  color: var(--ink);
}

.form-field textarea {
  min-height: 125px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #778087;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--accent);
  outline: 2px solid rgba(200, 121, 66, .18);
  outline-offset: 1px;
}

.form-submit {
  width: 100%;
  cursor: pointer;
}

.form-note {
  margin: 0;
  color: var(--ink-soft);
  font-size: .76rem;
  text-align: center;
}

.contact-quick-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 27px;
}

.contact-quick-actions a {
  color: var(--white);
  font-size: .85rem;
  font-weight: 700;
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, .45);
  text-underline-offset: 5px;
}

.site-footer {
  padding-block: 35px;
  background: #0c1c25;
  color: rgba(255, 255, 255, .7);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.footer-brand {
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.15rem;
}

.footer-copy {
  margin: 0;
  font-size: .78rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
}

.footer-links a {
  color: rgba(255, 255, 255, .8);
  font-size: .8rem;
}

.footer-links a:hover {
  color: #efb486;
}

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--white);
  color: var(--navy);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

@media (max-width: 900px) {
  .header-inner {
    min-height: 76px;
    gap: 15px;
  }

  .menu-toggle {
    display: flex;
    flex: 0 0 46px;
  }

  .primary-nav {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    display: none;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    padding: 12px var(--gutter) 22px;
    border-top: 1px solid var(--line);
    background: var(--white);
    box-shadow: 0 15px 25px rgba(16, 35, 46, .1);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    padding: 13px 0;
    border-bottom: 1px solid var(--line);
  }

  .primary-nav .button {
    margin-top: 14px;
  }

  .hero {
    min-height: 650px;
  }

  .hero-content {
    padding-block: 90px;
  }

  .intro-layout,
  .process-layout,
  .contact-layout {
    grid-template-columns: 1fr;
  }

  .intro-image-wrap {
    max-width: 680px;
  }

  .services-layout {
    grid-template-columns: repeat(2, 1fr);
  }

  .projects-layout {
    grid-template-columns: 1fr;
  }

  .project-feature,
  .project-feature img {
    min-height: 420px;
  }

  .project-secondary {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto;
  }

  .project-secondary-item,
  .project-secondary-item img {
    min-height: 260px;
  }

  .contact-layout {
    gap: 45px;
  }

  .contact-copy {
    max-width: 650px;
  }
}

@media (max-width: 600px) {
  :root {
    --gutter: 22px;
  }

  body {
    font-size: 15px;
  }

  .section {
    padding-block: 72px;
  }

  .header-inner {
    min-height: 70px;
  }

  .brand {
    gap: 9px;
  }

  .brand-mark {
    width: 39px;
    height: 39px;
    flex-basis: 39px;
  }

  .brand-name {
    font-size: .96rem;
  }

  .brand-description {
    font-size: .55rem;
  }

  .primary-nav {
    max-height: calc(100svh - 70px);
    overflow-y: auto;
    overflow-x: hidden;
  }

  .primary-nav a {
    max-width: 100%;
    overflow-wrap: anywhere;
  }

  .hero {
    min-height: 670px;
    min-height: min(760px, calc(100svh - 70px));
    align-items: flex-end;
  }

  .hero-media {
    object-position: 58% center;
  }

  .hero::after {
    background: linear-gradient(
      0deg,
      rgba(12, 29, 39, .94) 0%,
      rgba(12, 29, 39, .79) 48%,
      rgba(12, 29, 39, .3) 100%
    );
  }

  .hero-content {
    padding-block: 65px 45px;
  }

  h1 {
    font-size: clamp(2.8rem, 13vw, 4.5rem);
  }

  h2 {
    font-size: clamp(2.25rem, 10vw, 3.2rem);
  }

  .hero-description {
    font-size: .98rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-proof {
    gap: 15px 25px;
    margin-top: 35px;
    padding-top: 20px;
  }

  .hero-proof-item strong {
    font-size: 1.4rem;
  }

  .section-heading {
    margin-bottom: 34px;
  }

  .intro-layout {
    gap: 35px;
  }

  .intro-image-wrap {
    min-height: 320px;
    padding-right: 8px;
  }

  .intro-image {
    height: 340px;
  }

  .intro-caption {
    right: 0;
    bottom: 14px;
    max-width: 190px;
    padding: 15px 18px;
  }

  .intro-caption strong {
    font-size: 1.4rem;
  }

  .services-layout {
    grid-template-columns: 1fr;
  }

  .service-item {
    min-height: 0;
    padding: 27px 24px;
  }

  .service-number {
    margin-bottom: 15px;
  }

  .projects-layout {
    gap: 17px;
  }

  .project-feature,
  .project-feature img {
    min-height: 350px;
  }

  .project-secondary {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .project-secondary-item,
  .project-secondary-item img {
    min-height: 245px;
  }

  .project-overlay {
    padding: 50px 20px 20px;
  }

  .process-layout {
    gap: 30px;
  }

  .process-step {
    grid-template-columns: 42px 1fr;
    gap: 13px;
    padding: 22px 0;
  }

  .process-step-number {
    font-size: 1.5rem;
  }

  .contact-form {
    gap: 16px;
    padding: 23px 18px;
  }

  .form-row {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .contact-quick-actions {
    flex-direction: column;
    align-items: flex-start;
  }

  .footer-inner {
    align-items: flex-start;
    flex-direction: column;
    gap: 16px;
  }

  .footer-links {
    gap: 12px 20px;
  }
}

@media (max-width: 360px) {
  .brand-name {
    font-size: .85rem;
  }

  .brand-description {
    font-size: .49rem;
    letter-spacing: .08em;
  }

  .hero-proof {
    gap: 12px;
  }

  .hero-proof-item {
    font-size: .7rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

@media (prefers-contrast: more) {
  :root {
    --ink-soft: #35434b;
    --line: #9ba2a3;
  }

  .hero-description,
  .services-section .section-heading p,
  .service-item p,
  .contact-copy > p {
    color: var(--white);
  }

  .form-field input,
  .form-field select,
  .form-field textarea {
    border-color: #737d82;
  }
}
```
